initialize:
// ============================================================
//  MadridMove – zentrale Konfiguration der Node-RED-Dienste
//  (Collector und Client sind Python-Programme, Einstellungen in python/config.py)
//  Werte lassen sich per Umgebungsvariable überschreiben, z. B. ORS_API_KEY=abc node-red
// ============================================================
const cfg = {
    // Topic-Präfix: wird von configure.py gesetzt, nicht von Hand ändern
    prefix: 'upm-dsiot-g6/move',

    apis: {
        // openrouteservice (Fahrzeit, Höhenmeter; kostenloser Schlüssel, optional)
        ors: env.get('ORS_URL') || 'https://api.openrouteservice.org',
        orsKey: env.get('ORS_API_KEY') || ''
    },

    reco: {
        // Persönliche Grenzen, solange ein Nutzer nichts eingestellt hat ("vorsichtig")
        defaultSettings: { rain: 'kein', windMax: 25, tempMin: 8, tempMax: 30 },
        rainLight: 0.1,          // mm pro 15 min = leichter Regen (Grenze bei "kein Regen")
        rainHeavy: 1.0,          // mm pro 15 min = starker Regen (Grenze bei "leichter Regen ok")

        okBikes: 3,              // ab so vielen Rädern gilt eine Station als sicher
        nearbyStationM: 500,     // Umkreis für Ausweichstationen
        altFasterMin: 5,         // Warnung, wenn zu Fuß/ÖPNV mind. so viel schneller ist
        dockMin: 2,              // Ausleihen + Abstellen
        minPerHmUp: 0.05,        // Aufschlag pro Höhenmeter bergauf (3 s; BiciMAD = E-Bikes)

        windowMin: 30,           // Meldungen nur so viele Minuten vor der Abfahrt
        preInfoMin: 15,          // Vorab-Info so viele Minuten vor der Abfahrt
        staleMin: 15,            // BiciMAD-Daten älter als das = veraltet
        weatherStaleMin: 30,     // Wetterdaten älter als das = veraltet
        maxRoutesPerUser: 3,

        // Streckenprofil ohne ORS (Schätzmodus) und ÖPNV-Schätzung (kein Fahrplan)
        bikeSpeedKmh: 14,
        walkSpeedKmh: 4.8,
        detourFactor: 1.3,       // Luftlinie -> Straßenweg
        transitSpeedKmh: 18,
        transitAccessMin: 8,     // Wege zur und von der Haltestelle
        transitWaitMin: 4,       // mittlere Wartezeit (ersetzt durch EMT-Livedaten, wenn vorhanden)

        // EMT-Busankünfte (Python-Collector mit Zugangsdaten in python/secrets.env)
        busFreshMin: 4,          // Busdaten älter als das werden ignoriert
        busApplyMin: 20,         // nur für Fahrten, die in höchstens so vielen Minuten starten
        walkMPerMin: 80          // Fußweg zur Haltestelle (ca. 4,8 km/h)
    },

    // Statistik für die Diagramme (Tab "Statistik")
    stats: {
        center: { lat: 40.4169, lon: -3.7035 },  // Puerta del Sol
        centerRadiusKm: 3,       // bis hier "Zentrum", danach "Stadtrand"
        freshMin: 20,            // nur Stationen mit Daten jünger als das
        waveEveryMin: 5,         // Pendlerwelle: ein Punkt alle 5 min
        waveKeepH: 24,           // ... für 24 h
        useEveryMin: 10,         // Wetter und Radnutzung: Bewegungen je 10 min
        useKeepD: 3              // ... für 3 Tage
    }
};
global.set('cfg', cfg);
node.status({
    fill: cfg.apis.orsKey ? 'green' : 'yellow', shape: 'dot',
    text: cfg.apis.orsKey ? 'ORS-Schlüssel gesetzt' : 'kein ORS-Schlüssel: Schätzmodus'
});

func:
// Merkt sich die Stationsliste (.../static/stations, retained).
// Routen, die vorher eingetroffen sind, werden jetzt nachträglich verarbeitet.
const list = Array.isArray(msg.payload) ? msg.payload : [];
const map = {};
for (const s of list) map[s.id] = s;
flow.set('stations', map);
node.status({ fill: 'green', shape: 'dot', text: list.length + ' Stationen bekannt' });
const pending = flow.get('pending') || {};
flow.set('pending', {});
return [Object.values(pending)];

// Merkt sich, für welche Routen schon ein Profil existiert (retained).
// So wird nach einem Neustart nicht jede Route erneut bei ORS angefragt.
const cfg = global.get('cfg');
// Zustand verwerfen, wenn sich das Präfix geändert hat (Context überlebt einen Deploy)
let cache = flow.get('profiles');
if (!cache || cache.__prefix !== cfg.prefix) cache = { __prefix: cfg.prefix };
const key = msg.topic.split('/').slice(-2).join('/');
const empty = msg.payload === '' || msg.payload == null ||
    (Buffer.isBuffer(msg.payload) && msg.payload.length === 0);
if (empty) delete cache[key];
else if (typeof msg.payload === 'object') cache[key] = msg.payload.orsError ? null : msg.payload.routeHash;
flow.set('profiles', cache);
return null;

// Eingang für Routen: .../routes/<nutzer>/<route-id>
// Payload: {"name":"Zur Uni","from":{"label":"Calle de Alcalá 50","lat":40.42,"lon":-3.69},"to":{...}}
//   (ältere Routen mit {"id":"57"} = Stations-ID werden weiterhin verstanden)
// Für Start und Ziel wird jeweils die nächstgelegene BiciMAD-Station bestimmt.
// Leere Retained-Nachricht = Route gelöscht -> Profil ebenfalls löschen.
// Ausgang 1: Profil löschen | 2: ORS Fahrrad | 3: ohne ORS (Schätzung) | 4: ORS nur Fußweg
const cfg = global.get('cfg');
const R = cfg.reco;
const parts = msg.topic.split('/');
const user = parts[parts.length - 2], routeId = parts[parts.length - 1];
const key = user + '/' + routeId;
const profileTopic = cfg.prefix + '/profiles/' + key;

const empty = msg.payload === '' || msg.payload == null ||
    (Buffer.isBuffer(msg.payload) && msg.payload.length === 0);
if (empty) {
    node.status({ fill: 'grey', shape: 'dot', text: 'gelöscht: ' + key });
    return [{ topic: profileTopic, payload: '', qos: 1, retain: true }, null, null, null];
}
const r = msg.payload;
if (typeof r !== 'object' || !r.from || !r.to) {
    node.warn('Ungültige Route auf ' + msg.topic + ': ' + JSON.stringify(r));
    return null;
}
const stations = flow.get('stations');
if (!stations || Object.keys(stations).length === 0) {
    const pending = flow.get('pending') || {};
    pending[key] = msg;
    flow.set('pending', pending);
    node.status({ fill: 'yellow', shape: 'ring', text: 'warte auf Stationsliste' });
    return null;
}

// Entfernung in Metern (Näherung, für Stadtentfernungen ausreichend)
const dist = (a, b) => {
    const kx = 111320 * Math.cos(a.lat * Math.PI / 180), ky = 110540;
    return Math.hypot((a.lon - b.lon) * kx, (a.lat - b.lat) * ky);
};
// Punkt bestimmen: Koordinaten oder (alt) Stations-ID
const toPoint = (p) => {
    if (typeof p.lat === 'number' && typeof p.lon === 'number')
        return { label: p.label || p.address || (p.lat.toFixed(4) + ', ' + p.lon.toFixed(4)), address: p.address || null, lat: p.lat, lon: p.lon };
    if (p.id != null && stations[String(p.id)]) {
        const s = stations[String(p.id)];
        return { label: s.name, address: null, lat: s.lat, lon: s.lon };
    }
    return null;
};
const nearest = (pt) => {
    let best = null, bestD = Infinity;
    for (const s of Object.values(stations)) {
        const d = dist(pt, s);
        if (d < bestD) { bestD = d; best = s; }
    }
    return best;
};
const fromPoint = toPoint(r.from), toPointObj = toPoint(r.to);
if (!fromPoint || !toPointObj) {
    node.warn('Start oder Ziel ohne Koordinaten für ' + key + ': ' + JSON.stringify(r));
    return null;
}
const sFrom = nearest(fromPoint), sTo = nearest(toPointObj);
// Fußweg Adresse <-> Station: Luftlinie x Umwegfaktor (kurze Strecken, Schätzung genügt)
const leg = (a, s) => {
    const m = dist(a, s);
    return { distM: Math.round(m), walkMin: Math.round(m * R.detourFactor / 1000 / R.walkSpeedKmh * 600) / 10 };
};
const from = Object.assign({}, sFrom, leg(fromPoint, sFrom));
const to = Object.assign({}, sTo, leg(toPointObj, sTo));
const sameStation = from.id === to.id;

const source = cfg.apis.orsKey ? 'ors' : 'est';
const r4 = x => x.toFixed(4);
const routeHash = [r4(fromPoint.lat), r4(fromPoint.lon), r4(toPointObj.lat), r4(toPointObj.lon), from.id, to.id, source].join('|');
let cache = flow.get('profiles');
if (!cache || cache.__prefix !== cfg.prefix) { cache = { __prefix: cfg.prefix }; flow.set('profiles', cache); }
if (cache[key] === routeHash) {
    node.status({ fill: 'green', shape: 'ring', text: 'unverändert: ' + key });
    return null;
}
const job = {
    user: user, routeId: routeId, key: key, name: r.name || routeId,
    fromPoint: fromPoint, toPoint: toPointObj, from: from, to: to, sameStation: sameStation,
    air: dist(fromPoint, toPointObj), profileTopic: profileTopic, routeHash: routeHash
};
node.status({ fill: 'blue', shape: 'dot', text: 'berechne ' + key });
if (!cfg.apis.orsKey) return [null, null, { job: job }, null];

const headers = { 'Authorization': cfg.apis.orsKey, 'Content-Type': 'application/json', 'Accept': 'application/json' };
if (sameStation) {
    // Start und Ziel nutzen dieselbe Station: Fahrrad entfällt, nur Fußweg berechnen
    return [null, null, null, {
        job: job, url: cfg.apis.ors + '/v2/directions/foot-walking', headers: headers,
        payload: { coordinates: [[fromPoint.lon, fromPoint.lat], [toPointObj.lon, toPointObj.lat]], instructions: false }
    }];
}
// Fahrrad: von Station zu Station (dort wird das Rad geliehen und abgegeben)
return [null, {
    job: job, url: cfg.apis.ors + '/v2/directions/cycling-regular', headers: headers,
    payload: {
        coordinates: [[from.lon, from.lat], [to.lon, to.lat]],
        elevation: true,
        extra_info: ['waytype', 'steepness'],
        instructions: false
    }
}, null, null];

// Wertet die ORS-Fahrradroute aus: Länge, Dauer, Höhenmeter, Radweganteil.
// Ausgang 1: weiter zur Fußweg-Anfrage | 2: direkt zum Profil (bei Fehler)
const cfg = global.get('cfg');
const job = msg.job;
const r = msg.statusCode === 200 && msg.payload && msg.payload.routes && msg.payload.routes[0];
if (!r) {
    job.orsError = 'ORS Fahrrad: HTTP ' + msg.statusCode + ' ' +
        JSON.stringify(msg.payload && msg.payload.error || msg.payload).slice(0, 200);
    node.status({ fill: 'red', shape: 'ring', text: 'ORS-Fehler ' + msg.statusCode });
    node.warn(job.orsError);
    return [null, { job: job }];
}
const s = r.summary || {};
// Wegarten (waytype): 6 = Cycleway (Radweg). amount = Anteil in %
const wt = (r.extras && r.extras.waytype && r.extras.waytype.summary) || [];
const cycleway = wt.filter(w => w.value === 6).reduce((a, w) => a + w.amount, 0);
// Steigungsklassen (steepness): 3 = 7 bis <10 %, 4 = 10 bis <16 %, 5 = ab 16 %
const st = (r.extras && r.extras.steepness && r.extras.steepness.summary) || [];
const steep = st.filter(x => x.value >= 3).reduce((a, x) => a + x.amount, 0);
job.bike = {
    km: s.distance / 1000,
    min: s.duration / 60,
    ascent: s.ascent != null ? s.ascent : (r.ascent != null ? r.ascent : null),
    descent: s.descent != null ? s.descent : (r.descent != null ? r.descent : null),
    cyclewayPct: Math.round(cycleway),
    steepPct: Math.round(steep)
};
node.status({ fill: 'green', shape: 'dot', text: job.key + ': ' + job.bike.km.toFixed(1) + ' km' });
return [{
    job: job,
    url: cfg.apis.ors + '/v2/directions/foot-walking',
    headers: {
        'Authorization': cfg.apis.orsKey,
        'Content-Type': 'application/json',
        'Accept': 'application/json'
    },
    payload: {
        // Fußweg komplett: von Adresse zu Adresse
        coordinates: [[job.fromPoint.lon, job.fromPoint.lat], [job.toPoint.lon, job.toPoint.lat]],
        instructions: false
    }
}, null];

// Baut das Streckenprofil und veröffentlicht es retained auf
// .../profiles/<nutzer>/<route-id>. Fehlende ORS-Daten werden geschätzt.
const cfg = global.get('cfg');
const R = cfg.reco;
const job = msg.job;

// Fußweg-Antwort von ORS (falls vorhanden)
if (typeof msg.url === 'string' && msg.url.indexOf('foot-walking') >= 0) {
    const r = msg.statusCode === 200 && msg.payload && msg.payload.routes && msg.payload.routes[0];
    if (r) job.walk = { km: r.summary.distance / 1000, min: r.summary.duration / 60 };
    else job.orsError = (job.orsError ? job.orsError + ' | ' : '') + 'ORS Fußweg: HTTP ' + msg.statusCode;
}

const r1 = x => x == null ? null : Math.round(x * 10) / 10;
const dist = (a, b) => {
    const kx = 111320 * Math.cos(a.lat * Math.PI / 180), ky = 110540;
    return Math.hypot((a.lon - b.lon) * kx, (a.lat - b.lat) * ky);
};
// Schätzungen, falls ORS fehlt
const roadKm = job.air / 1000 * R.detourFactor;
let bike = null;
if (!job.sameStation) {
    const stKm = dist(job.from, job.to) / 1000 * R.detourFactor;
    bike = job.bike || { km: stKm, min: stKm / R.bikeSpeedKmh * 60, ascent: null, descent: null, cyclewayPct: null, steepPct: null };
}
const walk = job.walk || { km: roadKm, min: roadKm / R.walkSpeedKmh * 60 };
// ÖPNV-Schätzung: Fußwege zur/von der Haltestelle + Warten + Fahrt (Straßenweg Adresse -> Adresse)
const transitMin = R.transitAccessMin + R.transitWaitMin + walk.km / R.transitSpeedKmh * 60;
const usedOrs = !!(job.bike || job.walk);
const st = s => ({ id: s.id, name: s.name, lat: s.lat, lon: s.lon, capacity: s.capacity, distM: s.distM, walkMin: s.walkMin });

const profile = {
    user: job.user,
    route: job.routeId,
    name: job.name,
    fromPoint: job.fromPoint,          // Startadresse
    toPoint: job.toPoint,              // Zieladresse
    from: st(job.from),                // nächste Station am Start (+ Fußweg dorthin)
    to: st(job.to),                    // nächste Station am Ziel (+ Fußweg von dort)
    sameStation: job.sameStation,
    bike: bike && {                    // Station -> Station
        km: r1(bike.km), min: r1(bike.min), ascent: r1(bike.ascent), descent: r1(bike.descent),
        cyclewayPct: bike.cyclewayPct, steepPct: bike.steepPct
    },
    walk: { km: r1(walk.km), min: r1(walk.min) },   // Adresse -> Adresse
    transit: { min: r1(transitMin), estimated: true },
    source: usedOrs ? 'openrouteservice' : 'Schätzung (Luftlinie)',
    orsError: job.orsError || null,
    routeHash: job.routeHash,
    computedAt: new Date().toISOString()
};
// Bei ORS-Fehler nicht cachen, damit beim nächsten Mal neu versucht wird
let cache = flow.get('profiles');
if (!cache || cache.__prefix !== cfg.prefix) cache = { __prefix: cfg.prefix };
cache[job.key] = (cfg.apis.orsKey && !usedOrs) ? null : job.routeHash;
flow.set('profiles', cache);
node.status({ fill: 'green', shape: 'dot', text: job.key + ' (' + profile.source + ')' });
return { topic: job.profileTopic, payload: profile, qos: 1, retain: true };

// ============================================================
//  Empfehlungsdienst: "Kann ich meine BiciMAD-Fahrt wie geplant machen?"
//  Eingänge (alle per Wildcard abonniert, retained):
//    .../profiles/+/+         Streckenprofil (Fahrzeit, Fußweg, ÖPNV-Schätzung)
//    .../routes/+/+           Abfahrtszeit und Wochentage
//    .../users/+/settings     persönliche Grenzen (Regen, Wind, Temperatur)
//    .../static/stations      Stationsliste (für Ausweichstationen)
//    .../live/bicimad/+       Räder/Plätze je Station
//    .../live/weather         aktuelles Wetter + Vorhersage (15-min-Schritte)
//    .../system/+             Status der Collectors (Birth / Close / Last Will)
//    .../live/emt/+/+         nächste Busse an der Haltestelle am Startpunkt (nur mit EMT-Zugang)
//    .../plan/+/+             beste direkte Busverbindung laut Fahrplan (GTFS) zur nächsten Abfahrt
//    Takt alle 60 s           Zeitfenster, Vorab-Info, veraltete Daten
//  Ausgänge:
//    .../reco/<nutzer>/<route>   Status der Route (geplant / ok / warn / unbekannt), QoS 1, retained
//    .../alerts/<nutzer>         Meldungen, QoS 1, nicht retained
//
//  Das Rad ist gesetzt. Eine Warnung gibt es, wenn
//    - das Wetter während der Fahrt (Vorhersage) die persönliche Grenze überschreitet,
//    - an der Startstation und im Umkreis keine Räder sind,
//    - zu Fuß oder ÖPNV mindestens reco.altFasterMin Minuten schneller ist.
//  Empfehlung und Meldungen nur im Zeitfenster vor der Abfahrt (reco.windowMin):
//    Vorab-Info (reco.preInfoMin vorher), Warnung, Entwarnung (nur nach einer Warnung).
//  Vorher ist die Route "geplant": Fahrzeit, Wetter-Vorschau (Vorhersage bis 24 h) und
//  Busvergleich, aber kein Urteil und keine Räder (Räder sind nur kurzfristig aussagekräftig).
// ============================================================
const cfg = global.get('cfg');
const R = cfg.reco, P = cfg.prefix;
let st = context.get('st');
// Zustand verwerfen, wenn sich das Präfix geändert hat (Context überlebt einen Deploy)
if (st && !st.bus) st.bus = {};
if (st && !st.plan) st.plan = {};
if (!st || st.prefix !== P || !st.v2) {
    st = { v2: true, prefix: P, profiles: {}, routes: {}, settings: {}, stations: {}, bikes: {},
        weather: null, system: {}, sysAt: {}, last: {}, occ: {}, fresh: {}, bus: {}, plan: {} };
    context.set('pending', {});
}
const t = msg.topic || '';
const isEmpty = msg.payload === '' || msg.payload == null ||
    (Buffer.isBuffer(msg.payload) && msg.payload.length === 0);
const keyOf = () => t.split('/').slice(-2).join('/');
const allKeys = () => Object.keys(st.profiles);
let affected = [];

if (t.indexOf('/profiles/') >= 0) {
    const key = keyOf();
    if (isEmpty) {
        delete st.profiles[key];
        delete st.last[key];
        context.set('st', st);
        node.status({ fill: 'grey', shape: 'dot', text: 'Route entfernt: ' + key });
        return [[{ topic: P + '/reco/' + key, payload: '', qos: 1, retain: true }]];
    }
    st.profiles[key] = msg.payload;
    if (!msg.retain) st.fresh[key] = true;     // frisch berechnet = neue oder geänderte Route
    affected = [key];
} else if (t.indexOf('/routes/') >= 0) {
    const key = keyOf();
    if (isEmpty || typeof msg.payload !== 'object') delete st.routes[key];
    else st.routes[key] = { departure: msg.payload.departure || null };
    affected = st.profiles[key] ? [key] : [];
} else if (t.indexOf('/users/') >= 0 && t.endsWith('/settings')) {
    const user = t.split('/').slice(-2)[0];
    if (isEmpty || typeof msg.payload !== 'object') delete st.settings[user];
    else st.settings[user] = msg.payload;
    affected = allKeys().filter(k => k.split('/')[0] === user);
} else if (t.endsWith('/static/stations')) {
    st.stations = {};
    (Array.isArray(msg.payload) ? msg.payload : []).forEach(s => { st.stations[s.id] = s; });
    affected = allKeys();
} else if (t.indexOf('/live/bicimad/') >= 0) {
    if (typeof msg.payload !== 'object' || isEmpty) return null;
    const id = t.split('/').pop();
    st.bikes[id] = msg.payload;
    // betroffen: Routen, deren Startstation diese ist oder in deren Umkreis sie liegt
    affected = allKeys().filter(k => {
        const p = st.profiles[k];
        if (p.from.id === id || p.to.id === id) return true;
        const s = st.stations[id];
        return s && dist(s, p.from) <= R.nearbyStationM;
    });
} else if (t.endsWith('/live/weather')) {
    if (typeof msg.payload !== 'object' || isEmpty) return null;
    st.weather = msg.payload;
    affected = allKeys();
} else if (t.indexOf('/plan/') >= 0) {
    const key = keyOf();
    if (isEmpty || typeof msg.payload !== 'object') delete st.plan[key];
    else st.plan[key] = msg.payload;
    affected = st.profiles[key] ? [key] : [];
} else if (t.indexOf('/live/emt/') >= 0) {
    const key = keyOf();
    if (isEmpty || typeof msg.payload !== 'object') delete st.bus[key];
    else st.bus[key] = msg.payload;
    affected = st.profiles[key] ? [key] : [];
} else if (t.indexOf('/system/') >= 0) {
    const name = t.split('/').pop();
    st.system[name] = String(msg.payload);
    st.sysAt[name] = Date.now();
    affected = allKeys();
} else {
    affected = allKeys();   // Takt
}

function dist(a, b) {
    const kx = 111320 * Math.cos(a.lat * Math.PI / 180), ky = 110540;
    return Math.hypot((a.lon - b.lon) * kx, (a.lat - b.lat) * ky);
}
const DAYS = ['', 'Mo', 'Di', 'Mi', 'Do', 'Fr', 'Sa', 'So'];
const hm = ms => new Date(ms).toLocaleTimeString('de-DE', { timeZone: 'Europe/Madrid', hour: '2-digit', minute: '2-digit' });
const num = x => String(Math.round(x * 10) / 10).replace('.', ',');

// ---------- Uhrzeit in Madrid (Node-RED läuft evtl. in UTC) ----------
function madridNow() {
    const parts = {};
    new Intl.DateTimeFormat('en-GB', {
        timeZone: 'Europe/Madrid', weekday: 'short', year: 'numeric', month: '2-digit',
        day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false
    }).formatToParts(new Date()).forEach(p => { parts[p.type] = p.value; });
    const wd = { Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6, Sun: 7 }[parts.weekday];
    return { wd: wd, min: (Number(parts.hour) % 24) * 60 + Number(parts.minute),
        date: parts.year + '-' + parts.month + '-' + parts.day };
}
// 'heute' / 'morgen' / Wochentag für einen Zeitpunkt (Madrider Datum)
function dayLabel(ms) {
    const ymd = d => new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Madrid' }).format(new Date(d));
    if (ymd(ms) === ymd(Date.now())) return 'heute';
    if (ymd(ms) === ymd(Date.now() + 86400000)) return 'morgen';
    const wd = new Intl.DateTimeFormat('en-GB', { timeZone: 'Europe/Madrid', weekday: 'short' }).format(new Date(ms));
    return DAYS[{ Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6, Sun: 7 }[wd]];
}
function daysText(days) {
    const d = (days || []).slice().sort();
    if (d.join() === '1,2,3,4,5') return 'Mo–Fr';
    if (d.length === 7) return 'täglich';
    if (d.join() === '6,7') return 'Sa–So';
    return d.map(x => DAYS[x]).join(', ');
}
// Nächste Abfahrt (heute oder in den nächsten 7 Tagen)
function schedule(dep) {
    if (!dep || !/^\d{1,2}:\d{2}$/.test(dep.time || '') || !Array.isArray(dep.days) || !dep.days.length) return null;
    const now = madridNow();
    const [h, m] = dep.time.split(':').map(Number);
    for (let off = 0; off <= 7; off++) {
        const wd = ((now.wd - 1 + off) % 7) + 1;
        if (dep.days.indexOf(wd) < 0) continue;
        const diff = off * 1440 + h * 60 + m - now.min;
        if (diff < 0) continue;
        return {
            minutesLeft: diff,
            inWindow: diff <= R.windowMin,
            at: Math.floor(Date.now() / 60000) * 60000 + diff * 60000,
            nextText: (off === 0 ? 'heute' : off === 1 ? 'morgen' : DAYS[wd]) + ' ' + dep.time,
            occurrence: now.date + '+' + off + '|' + dep.time
        };
    }
    return null;
}

// ---------- Wetter während der Fahrt ----------
function tripWeather(from, to) {
    const w = st.weather;
    if (!w) return null;
    const alive = (st.system.weather || '').indexOf('online') === 0 || w.ts > (st.sysAt.weather || 0);
    if (!alive || Date.now() - w.ts > R.weatherStaleMin * 60000) return null;
    // Vorhersage-Slots (15 min), die sich mit [Abfahrt, Ankunft] überschneiden
    const slots = (w.forecast || []).filter(f => f.t + 15 * 60000 > from && f.t <= to);
    const src = slots.length ? slots : [{ t: from, temp: w.temp, precip: w.precip, wind: w.wind }];
    return {
        source: slots.length ? 'Vorhersage' : 'aktuell',
        slots: src,
        maxPrecip: Math.max(...src.map(s => s.precip || 0)),
        maxWind: Math.max(...src.map(s => s.wind || 0)),
        minTemp: Math.min(...src.map(s => s.temp)),
        maxTemp: Math.max(...src.map(s => s.temp))
    };
}

function evaluate(key, p) {
    const now = Date.now();
    const user = key.split('/')[0];
    const set = Object.assign({}, R.defaultSettings, st.settings[user] || {});
    const dep = (st.routes[key] || {}).departure || null;
    const sch = schedule(dep);
    const planned = !!(sch && !sch.inWindow);           // vor dem Zeitfenster: nur Vorschau
    const windowStart = sch ? sch.at - R.windowMin * 60000 : null;
    const problems = [], hints = [], notes = [];

    // ---------- Fahrzeit ----------
    let bikeMin = (p.bike ? p.bike.min : 0) + R.dockMin;
    if (p.bike && p.bike.ascent) bikeMin += p.bike.ascent * R.minPerHmUp;   // E-Bike: wenig Aufschlag
    bikeMin = Math.round(bikeMin);

    // ---------- Räder an der Startstation ----------
    const sysB = st.system.bicimad || '';
    const bAlive = id => st.bikes[id] && ((sysB.indexOf('online') === 0) || st.bikes[id].ts > (st.sysAt.bicimad || 0));
    const fresh = id => bAlive(id) && now - st.bikes[id].ts < R.staleMin * 60000;
    const sFrom = st.bikes[p.from.id], sTo = st.bikes[p.to.id];
    let dataMissing = false, alt = null;
    const avail = s => (s && s.renting !== false) ? s.bikes : 0;
    if (planned) {
        // Räder erst im Zeitfenster bewerten
    } else if (!fresh(p.from.id)) {
        dataMissing = true;
        notes.push('BiciMAD-Daten fehlen' + (sysB ? ' (' + sysB + ')' : ''));
    } else if (avail(sFrom) < R.okBikes) {
        // Ausweichstation: nächste Station im Umkreis mit genug Rädern
        const base = st.stations[p.from.id] || p.from;
        alt = Object.values(st.stations)
            .filter(s => s.id !== p.from.id && fresh(s.id) && avail(st.bikes[s.id]) >= R.okBikes)
            .map(s => ({ id: s.id, name: s.name, distM: Math.round(dist(base, s) / 10) * 10, bikes: avail(st.bikes[s.id]) }))
            .filter(s => s.distM <= R.nearbyStationM)
            .sort((a, b) => a.distM - b.distM)[0] || null;
        const n = avail(sFrom);
        const here = (n === 0 ? 'keine Räder' : 'nur ' + n + (n === 1 ? ' Rad' : ' Räder')) + ' an ' + p.from.name;
        if (alt) hints.push(here + ' – Ausweichstation ' + alt.name + ' (' + alt.distM + ' m, ' + alt.bikes + ' Räder)');
        else problems.push(here + ', auch im Umkreis von ' + R.nearbyStationM + ' m');
    }

    // ---------- Wetter während der Fahrt ----------
    const startT = sch ? sch.at : now;
    let tw = tripWeather(startT, startT + bikeMin * 60000);
    if (planned && tw && tw.source !== 'Vorhersage') {
        tw = null;                                          // Abfahrt liegt hinter der Vorhersage (24 h)
        notes.push('Wetter-Vorschau, sobald die Abfahrt weniger als 24 h entfernt ist');
    } else if (!tw) {
        notes.push('Wetterdaten fehlen (' + (st.system.weather || 'unbekannt') + ')');
        if (!planned) dataMissing = true;                   // ohne Wetter kein Urteil (keine falsche Entwarnung)
    }
    else {
        const rainLimit = set.rain === 'kein' ? R.rainLight : set.rain === 'leicht' ? R.rainHeavy : Infinity;
        if (tw.maxPrecip >= rainLimit) {
            const first = tw.slots.find(s => (s.precip || 0) >= rainLimit);
            const when = tw.source !== 'Vorhersage' ? '' :
                (first && first.t > startT ? ' ab ' + hm(first.t) : ' während der Fahrt') + ' erwartet';
            problems.push((tw.maxPrecip >= R.rainHeavy ? 'starker Regen' : 'Regen') + when +
                ' (' + num(tw.maxPrecip) + ' mm)');
        }
        if (tw.maxWind > set.windMax) problems.push('Wind bis ' + Math.round(tw.maxWind) + ' km/h (deine Grenze ' + set.windMax + ')');
        if (tw.minTemp < set.tempMin) problems.push('nur ' + Math.round(tw.minTemp) + ' °C (deine Grenze ' + set.tempMin + ' °C)');
        if (tw.maxTemp > set.tempMax) problems.push(Math.round(tw.maxTemp) + ' °C (deine Grenze ' + set.tempMax + ' °C)');
    }

    // ---------- ÖPNV: Fahrplan (GTFS) > EMT live > Schätzung ----------
    let transitMin = Math.round(p.transit.min), transitLabel = 'ÖPNV (Schätzung)', bus = null, plan = null, noTransit = false;
    const leaveIn = sch ? sch.minutesLeft : 0;
    const b = st.bus[key];
    let arr = [];
    const walk = a => Math.ceil(((a.distM != null ? a.distM : (b && b.stop.distM)) || 0) / R.walkMPerMin);
    if (b && b.stop && now - b.ts < R.busFreshMin * 60000) {
        // Live-Ankünfte an bis zu 3 Haltestellen im Umkreis (Minuten seit dem Abruf abziehen)
        const elapsed = Math.floor((now - b.ts) / 60000);
        arr = (b.arrivals || []).map(a => Object.assign({}, a, { min: a.min - elapsed })).filter(a => a.min >= 0);
        bus = { stop: b.stop.name, distM: b.stop.distM, walkMin: walk(b.stop),
            next: arr.slice(0, 4).map(a => ({ line: a.line, min: a.min, destination: a.destination, stop: a.stop || b.stop.name })) };
    }
    // Fahrplan: nur wenn er für genau diese Abfahrt berechnet wurde
    const pl = st.plan[key];
    if (pl && (sch ? Math.abs(pl.depAt - sch.at) < 90000 : !pl.forDeparture && now - pl.depAt < 15 * 60000)) {
        plan = { status: pl.status, line: pl.line, headsign: pl.headsign, board: pl.board, alight: pl.alight,
            boardAt: pl.boardAt, headwayMin: pl.headwayMin, waitMin: pl.waitMin, rideMin: pl.rideMin, totalMin: pl.totalMin };
        if (pl.status === 'ok') { transitMin = pl.totalMin; transitLabel = 'ÖPNV (Fahrplan)'; }
        else if (pl.status === 'noservice') { noTransit = true; }
        // 'nodirect': keine direkte Linie -> Schätzung bleibt (mit Umsteigen evtl. möglich)
    }
    if (bus && leaveIn <= R.busApplyMin) {
        const norm = x => String(x).replace(/^0+(?=.)/, '').toUpperCase();
        if (plan && plan.status === 'ok') {
            // Fahrplan-Linie live an der Haltestelle? Dann echte statt geplanter Wartezeit
            const live = arr.find(a => norm(a.line) === norm(plan.line) && a.min >= leaveIn + plan.board.walkMin);
            if (live) {
                const wait = live.min - leaveIn - plan.board.walkMin;
                transitMin = Math.round(plan.board.walkMin + wait + plan.rideMin + plan.alight.walkMin);
                transitLabel = 'ÖPNV (Fahrplan + EMT live)';
                bus.used = { line: live.line, min: live.min, wait: wait, stop: live.stop || b.stop.name };
            }
        } else if (!plan) {
            // kein Fahrplan: nächster erreichbarer Bus, Fahrzeit geschätzt
            const catchable = arr.find(a => a.min >= leaveIn + walk(a));
            if (catchable) {
                const wait = catchable.min - leaveIn - walk(catchable);
                transitMin = Math.round(p.transit.min - R.transitWaitMin - R.transitAccessMin / 2 + walk(catchable) + wait);
                transitLabel = 'ÖPNV (EMT live)';
                bus.used = { line: catchable.line, min: catchable.min, wait: wait, stop: catchable.stop || b.stop.name };
            }
        }
    }

    // ---------- Alternativen ----------
    const alternatives = [{ mode: 'walk', label: 'zu Fuß', min: Math.round(p.walk.min) }];
    if (!noTransit) alternatives.push({ mode: 'transit', label: transitLabel, min: transitMin });
    alternatives.sort((a, b) => a.min - b.min);
    const faster = alternatives.find(a => a.min <= bikeMin - R.altFasterMin);
    if (faster) problems.push(faster.label.replace(/ \(.*\)/, '') + ' ' + (bikeMin - faster.min) +
        ' min schneller (' + faster.min + ' statt ' + bikeMin + ' min)');

    // ---------- Ergebnis ----------
    const status = planned ? 'geplant' : dataMissing ? 'unbekannt' : (problems.length ? 'warn' : 'ok');
    // geplant: mögliche Probleme nur als Vorschau, ohne Urteil
    const preview = planned ? problems.splice(0) : [];
    const weatherText = !tw ? 'Wetter unbekannt' :
        (tw.maxPrecip < R.rainLight ? 'trocken' : 'Regen bis ' + num(tw.maxPrecip) + ' mm') + ', ' +
        (tw.minTemp === tw.maxTemp || Math.round(tw.minTemp) === Math.round(tw.maxTemp) ? Math.round(tw.maxTemp) + ' °C'
            : Math.round(tw.minTemp) + '–' + Math.round(tw.maxTemp) + ' °C') +
        ', Wind ' + Math.round(tw.maxWind) + ' km/h';
    const bikesText = sFrom ? avail(sFrom) + (avail(sFrom) === 1 ? ' Rad' : ' Räder') + ' an ' + p.from.name : '';
    const tr = alternatives.find(a => a.mode === 'transit');
    const altText = (tr ? 'ÖPNV ca. ' + tr.min + ' min' : 'kein Bus zu dieser Zeit') + ', zu Fuß ' +
        alternatives.find(a => a.mode === 'walk').min + ' min';
    const headline = status === 'ok' ? '✓ Rad passt' : status === 'warn' ? '⚠ Heute lieber nicht Rad'
        : status === 'geplant' ? '🕒 Geplant · Empfehlung ab ' + hm(windowStart) : '? Daten fehlen';
    const detail = status === 'geplant' ? ['Abfahrt ' + sch.nextText,
            'ca. ' + bikeMin + ' min mit dem Rad', tw ? 'Vorschau: ' + weatherText : null,
            preview.length ? 'laut Vorhersage: ' + preview.join(', ') : null].filter(Boolean).join(' · ')
        : status === 'ok' ? [alt ? hints[0] : bikesText, weatherText, 'ca. ' + bikeMin + ' min'].filter(Boolean).join(' · ')
        : status === 'warn' ? problems.join(' · ') + '. Alternativen: ' + altText + (hints.length ? '. ' + hints[0] : '')
        : notes.join(' · ');
    return {
        user: p.user, route: p.route, name: p.name, from: p.from.name, to: p.to.name,
        status: status, headline: headline, detail: detail,
        problems: problems, preview: preview, hints: hints, notes: notes, alternatives: alternatives,
        bike: { min: bikeMin, bikes: (sFrom && !planned) ? avail(sFrom) : null, docks: (sTo && !planned) ? sTo.docks : null, alt: alt },
        bus: bus,
        plan: plan,
        weather: tw ? { text: weatherText, source: tw.source,
            from: hm(startT), to: hm(startT + bikeMin * 60000) } : null,
        settings: set,
        departure: dep ? { time: dep.time, days: dep.days, text: daysText(dep.days) + ' ' + dep.time } : null,
        nextDeparture: sch ? new Date(sch.at).toISOString() : null,
        nextDepartureText: sch ? sch.nextText : null,
        inWindow: !!(sch && sch.inWindow),
        windowStart: windowStart ? new Date(windowStart).toISOString() : null,
        windowStartText: windowStart ? hm(windowStart) : null,
        windowStartLabel: windowStart ? dayLabel(windowStart) + ' ' + hm(windowStart) : null,
        minutesLeft: sch ? sch.minutesLeft : null,
        _sch: sch,
        updated: new Date().toISOString()
    };
}

// Bündeln (Debounce): mehrere Updates kurz hintereinander -> einmal nach 1 s rechnen
const pending = context.get('pending') || {};
affected.forEach(k => { pending[k] = true; });
context.set('pending', pending);
context.set('st', st);
if (!context.get('timer')) {
    context.set('timer', true);
    setTimeout(flushPending, 1000);
}
return null;

function flushPending() {
    context.set('timer', false);
    const keys = Object.keys(context.get('pending') || {});
    context.set('pending', {});
    st = context.get('st');
    const out = [];
    for (const key of keys) {
        const p = st.profiles[key];
        if (!p) continue;
        const r = evaluate(key, p);
        const sch = r._sch;
        delete r._sch;
        const prev = st.last[key];
        // nur senden, wenn sich inhaltlich etwas geändert hat (ohne Zeitstempel/Minuten)
        // (Zielplätze und Details der Ausweichstation stehen nicht auf der Karte -> nicht vergleichen)
        const sig = JSON.stringify([r.status, r.detail, r.problems, r.preview, r.hints, r.notes, r.alternatives,
            r.bike.min, r.bike.bikes, r.bus, r.plan, r.weather, r.settings, r.departure, r.nextDeparture, r.inWindow]);
        if (!prev || prev.sig !== sig) out.push({ topic: P + '/reco/' + key, payload: r, qos: 1, retain: true });

        // ---------- Meldungen ----------
        const occKey = sch ? key + '|' + sch.occurrence : null;
        const occ = occKey ? (st.occ[occKey] = st.occ[occKey] || { t: Date.now() }) : null;
        const head = '„' + r.name + '“ (' + r.from + ' → ' + r.to + (sch ? ', ' + r.departure.time : '') + ')';
        let text = null;
        if (st.fresh[key] && !prev) {
            text = 'Route „' + r.name + '“ (' + r.from + ' → ' + r.to + ') gespeichert: ' +
                (r.departure ? r.departure.text : 'ohne Abfahrtszeit') +
                '. Empfehlung und Meldungen ab ' + R.windowMin + ' min vor der Abfahrt' +
                (r.status === 'geplant' ? ' (' + r.windowStartLabel + ')' : '') + '.';
        }
        delete st.fresh[key];
        if (sch && sch.inWindow && r.status !== 'unbekannt') {
            const msgOk = '✓ Rad passt für ' + head + ': ' + r.detail + '.';
            const msgWarn = '⚠ Heute lieber nicht Rad für ' + head + ': ' + r.detail + '.';
            let add = null;
            if (r.status === 'warn' && !occ.warned) {
                add = msgWarn; occ.warned = true; occ.pre = occ.pre || sch.minutesLeft <= R.preInfoMin;
            } else if (r.status === 'ok' && occ.warned) {
                add = '✓ Entwarnung für ' + head + ': Rad passt wieder. ' + r.detail + '.';
                occ.warned = false; occ.pre = occ.pre || sch.minutesLeft <= R.preInfoMin;
            } else if (!occ.pre && sch.minutesLeft <= R.preInfoMin) {
                add = (r.status === 'ok' ? msgOk : msgWarn) + ' Abfahrt in ' + sch.minutesLeft + ' min.';
                occ.pre = true;
            }
            if (add) text = text ? text + ' ' + add : add;
        }
        if (text) out.push({ topic: P + '/alerts/' + p.user, payload: text, qos: 1, retain: false });
        st.last[key] = { sig: sig, status: r.status };
    }
    for (const k of Object.keys(st.occ)) if (Date.now() - st.occ[k].t > 2 * 86400000) delete st.occ[k];
    context.set('st', st);
    node.status({ fill: 'green', shape: 'dot', text: Object.keys(st.profiles).length + ' Routen, ' + out.length +
        ' Nachrichten, ' + new Date().toLocaleTimeString('de-DE', { timeZone: 'Europe/Madrid' }) });
    if (out.length) node.send([out]);
}

// .../reco/+/+ -> Daten für die Routenkarten (eine Karte pro Route)
const cfg = global.get('cfg');
let recos = flow.get('recos');
if (!recos || recos.__prefix !== cfg.prefix) recos = { __prefix: cfg.prefix };
const key = msg.topic.split('/').slice(-2).join('/');
const empty = msg.payload === '' || msg.payload == null ||
    (Buffer.isBuffer(msg.payload) && msg.payload.length === 0);
if (empty || typeof msg.payload !== 'object') delete recos[key];
else recos[key] = msg.payload;
flow.set('recos', recos);
const routes = Object.keys(recos).filter(k => k !== '__prefix').sort().map(k => {
    const r = recos[k];
    return {
        key: k, user: r.user, name: r.name, from: r.from, to: r.to,
        status: r.status, headline: r.headline,
        problems: r.problems || [], preview: r.preview || [], hints: r.hints || [], notes: r.notes || [],
        alternatives: r.alternatives || [], bike: r.bike || {}, bus: r.bus || null, plan: r.plan || null, weather: r.weather,
        settings: r.settings, departureText: r.departure ? r.departure.text : null,
        nextDeparture: r.nextDeparture, nextDepartureText: r.nextDepartureText, windowStartText: r.windowStartText || null,
        windowMin: cfg.reco.windowMin
    };
});
return { payload: { routes: routes } };

// Formulare "Neue Route" und "Meine Einstellungen". Jedes Feld sendet mit eigenem msg.topic.
// Ausgang 1: MQTT (Route, Einstellungen, Löschen) | 2: Status Route | 3: Status Einstellungen
const cfg = global.get('cfg');
const P = cfg.prefix;
const D = cfg.reco.defaultSettings;
const f = flow.get('form') || {};
const slug = s => String(s || '').toLowerCase().normalize('NFD')
    .replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '').slice(0, 30);
const save = () => flow.set('form', f);
const stationName = id => ((flow.get('stations') || []).find(s => s.id === id) || {}).name;

switch (msg.topic) {
    case 'user': f.user = msg.payload; break;
    case 'name': f.name = msg.payload; break;
    case 'from': f.from = msg.payload; break;
    case 'to': f.to = msg.payload; break;
    case 'time': f.time = msg.payload; break;
    case 'days': f.days = (Array.isArray(msg.payload) ? msg.payload : [msg.payload]).map(Number).filter(Boolean); break;
    case 'rain': f.rain = msg.payload; break;
    case 'windMax': f.windMax = Number(msg.payload); break;
    case 'tempMin': f.tempMin = Number(msg.payload); break;
    case 'tempMax': f.tempMax = Number(msg.payload); break;
    case 'delSel': f.del = msg.payload; break;
    case 'create': {
        const u = slug(f.user), r = slug(f.name);
        if (!u || !r) return [null, { payload: '⚠ Bitte oben deinen Namen und einen Routennamen eingeben.' }, null];
        const a = stationName(f.from), b = stationName(f.to);
        if (!a || !b) return [null, { payload: '⚠ Bitte Start- und Zielstation auswählen.' }, null];
        if (f.from === f.to) return [null, { payload: '⚠ Start und Ziel sind dieselbe Station.' }, null];
        if (!/^\d{1,2}:\d{2}$/.test(String(f.time || ''))) return [null, { payload: '⚠ Bitte eine Abfahrtszeit eingeben (z. B. 08:30).' }, null];
        if (!f.days || !f.days.length) return [null, { payload: '⚠ Bitte mindestens einen Wochentag wählen.' }, null];
        const mine = Object.keys(flow.get('routeKeys') || {}).filter(k => k.split('/')[0] === u && k !== u + '/' + r);
        if (mine.length >= cfg.reco.maxRoutesPerUser) return [null, { payload: '⚠ Höchstens ' + cfg.reco.maxRoutesPerUser + ' Routen pro Nutzer.' }, null];
        save();
        const time = String(f.time).padStart(5, '0');
        const route = { name: f.name, from: { id: f.from, label: a }, to: { id: f.to, label: b },
            departure: { time: time, days: f.days.slice().sort() }, createdAt: new Date().toISOString() };
        return [{ topic: P + '/routes/' + u + '/' + r, payload: route, qos: 1, retain: true },
            { payload: '✔ Route ' + u + '/' + r + ' gespeichert: ' + a + ' → ' + b + ', ' + time + ' Uhr.' }, null];
    }
    case 'saveSettings': {
        const u = slug(f.user);
        if (!u) return [null, null, { payload: '⚠ Bitte oben deinen Namen eingeben.' }];
        const s = {
            rain: f.rain || D.rain,
            windMax: isFinite(f.windMax) && f.windMax > 0 ? f.windMax : D.windMax,
            tempMin: isFinite(f.tempMin) ? f.tempMin : D.tempMin,
            tempMax: isFinite(f.tempMax) ? f.tempMax : D.tempMax
        };
        if (s.tempMin >= s.tempMax) return [null, null, { payload: '⚠ Mindesttemperatur muss unter der Höchsttemperatur liegen.' }];
        save();
        const regen = { kein: 'kein Regen', leicht: 'leichter Regen ok', egal: 'Regen egal' }[s.rain];
        return [{ topic: P + '/users/' + u + '/settings', payload: s, qos: 1, retain: true }, null,
            { payload: '✔ Gespeichert für ' + u + ': ' + regen + ', Wind bis ' + s.windMax + ' km/h, ' + s.tempMin + ' bis ' + s.tempMax + ' °C.' }];
    }
    case 'delete': {
        if (!f.del) return [null, { payload: '⚠ Bitte eine Route zum Löschen wählen.' }, null];
        const key = f.del;
        f.del = null;
        save();
        // Leere Retained-Nachricht = gespeicherte Route auf dem Broker löschen
        return [{ topic: P + '/routes/' + key, payload: '', qos: 1, retain: true },
            { payload: '🗑 Route ' + key + ' gelöscht.' }, null];
    }
}
save();
return null;

// .../routes/+/+ -> Liste aller Routen (für "Route löschen" und die Obergrenze)
const cfg = global.get('cfg');
let routes = flow.get('routeKeys');
if (!routes || routes.__prefix !== cfg.prefix) routes = { __prefix: cfg.prefix };
const key = msg.topic.split('/').slice(-2).join('/');
const empty = msg.payload === '' || msg.payload == null ||
    (Buffer.isBuffer(msg.payload) && msg.payload.length === 0);
if (empty) delete routes[key];
else if (typeof msg.payload === 'object') routes[key] = msg.payload.name || key;
flow.set('routeKeys', routes);
const options = Object.keys(routes).filter(k => k !== '__prefix').sort().map(k => ({ label: k + ' – ' + routes[k], value: k }));
return { ui_update: { options: options.length ? options : [{ label: '(keine Routen)', value: '' }] } };

// .../system/+ -> Tabelle "Datenquellen"
const cfg = global.get('cfg');
let rows = context.get('rows');
if (!rows || rows.__prefix !== cfg.prefix) rows = { __prefix: cfg.prefix };
const name = msg.topic.split('/').pop();
const empty = msg.payload === '' || msg.payload == null || (Buffer.isBuffer(msg.payload) && msg.payload.length === 0);
if (empty) delete rows[name];          // leere retained Nachricht = Quelle nicht (mehr) eingerichtet
else rows[name] = {
    'Quelle': name,
    'Status': String(msg.payload),
    'Seit': new Date().toLocaleTimeString('de-DE', { timeZone: 'Europe/Madrid' })
};
context.set('rows', rows);
return { payload: Object.keys(rows).filter(k => k !== '__prefix').map(k => rows[k]) };

// .../live/weather -> Textzeile: aktuelles Wetter + Regen in der Vorhersage (nächste 2 h)
const w = msg.payload;
if (typeof w !== 'object' || w == null) return null;
const hm = ms => new Date(ms).toLocaleTimeString('de-DE', { timeZone: 'Europe/Madrid', hour: '2-digit', minute: '2-digit' });
const rain = (w.forecast || []).filter(f => f.t <= Date.now() + 2 * 3600000 && f.precip >= 0.1);
const fc = !(w.forecast || []).length ? '' : rain.length ? ' · Regen erwartet ab ' + hm(rain[0].t) : ' · nächste 2 h trocken';
return { payload: w.temp + ' °C · ' + w.precip + ' mm · Wind ' + w.wind + ' km/h' + fc +
    ' · Stand ' + hm(w.ts) };

// Demo-Route (Seite "System & Demo"): eine echte Route "Zur Uni" (Sol -> Ciudad Universitaria)
// für den Nutzer "demo", Abfahrt in 14 min (also sofort im Zeitfenster für Meldungen).
// Die Einstellungen von "demo" werden auf die Standardwerte zurückgesetzt, damit jede Probe gleich startet.
// Die Stationen werden über die Lage gesucht (nächste BiciMAD-Station zu Sol bzw. Ciudad Universitaria).
// Ausgang 1: MQTT   Ausgang 2: Hinweis im Feld "Status Demo-Route"
const cfg = global.get('cfg');
const P = cfg.prefix;
if (msg.topic !== 'demoroutes') return null;
const stations = flow.get('stations') || [];
if (!stations.length) {
    const t = '⚠ Noch keine Stationsliste. Läuft collector.py (Fenster offen, „verbunden“)? Ohne Internet nutzt er stations_cache.json.';
    node.warn(t);
    return [null, { payload: t }];
}
const dist = (a, b) => Math.hypot((a.lon - b.lon) * 85000, (a.lat - b.lat) * 111000);
const near = (lat, lon) => stations.slice().sort((a, b) => dist(a, { lat, lon }) - dist(b, { lat, lon }))[0];
const parts = {};
new Intl.DateTimeFormat('en-GB', { timeZone: 'Europe/Madrid', hour: '2-digit', minute: '2-digit', hour12: false })
    .formatToParts(new Date(Date.now() + 14 * 60000)).forEach(p => { parts[p.type] = p.value; });
const time = String(Number(parts.hour) % 24).padStart(2, '0') + ':' + parts.minute;
const a = near(40.4169, -3.7035), b = near(40.4437, -3.7276);          // Sol -> Ciudad Universitaria
const out = [
    { topic: P + '/users/demo/settings', payload: cfg.reco.defaultSettings, qos: 1, retain: true },
    { topic: P + '/routes/demo/zur-uni', qos: 1, retain: true,
      payload: { name: 'Zur Uni', from: { id: a.id, label: a.name }, to: { id: b.id, label: b.name },
          departure: { time: time, days: [1, 2, 3, 4, 5, 6, 7] }, createdAt: new Date().toISOString() } }
];
return [out, { payload: 'Demo-Route „Zur Uni“ angelegt (' + a.name + ' → ' + b.name + '), Abfahrt ' + time + ' (in 14 min).' }];

// Beim Start: Vorgaben ins Formular schreiben (Abfahrt 08:30, Mo–Fr, vorsichtige Grenzen)
const D = global.get('cfg').reco.defaultSettings;
const f = flow.get('form') || {};
f.time = f.time || '08:30';
f.days = (f.days && f.days.length) ? f.days : [1, 2, 3, 4, 5];
f.rain = f.rain || D.rain;
f.windMax = f.windMax || D.windMax;
f.tempMin = isFinite(f.tempMin) ? f.tempMin : D.tempMin;
f.tempMax = isFinite(f.tempMax) ? f.tempMax : D.tempMax;
flow.set('form', f);
return [{ payload: f.time }, { payload: f.days }, { payload: f.rain }, { payload: f.windMax },
    { payload: f.tempMin }, { payload: f.tempMax }];

// .../static/stations (retained) -> Auswahllisten Start- und Zielstation.
// Die Listen sind "Comboboxen": tippen filtert, z. B. "sol" oder die Stationsnummer.
const list = Array.isArray(msg.payload) ? msg.payload : [];
flow.set('stations', list);
const options = list.map(s => ({ label: s.name + ' (' + s.id + ')', value: s.id }));
node.status({ fill: 'green', shape: 'dot', text: list.length + ' Stationen' });
return { ui_update: { options: options.length ? options : [{ label: '(lädt …)', value: '' }] } };

// ============================================================
//  Statistik-Dienst: Kennzahlen für die Diagramme im Dashboard
//  Eingänge (Wildcard-Abos):
//    .../static/stations      Lage und Kapazität der Stationen
//    .../live/bicimad/+       Räder/Plätze je Station
//    .../live/weather         aktuelles Wetter
//    .../stats/history        eigener Verlauf (retained) -> wird nach einem Neustart übernommen
//    Takt jede Minute
//  Ausgänge (retained):
//    .../stats/now            aktuelle Kennzahlen (Räder frei, leere/volle Stationen, Bewegungen)
//    .../stats/spatial        je Station: Entfernung zur Puerta del Sol und Füllgrad
//    .../stats/history        Verlauf: Pendlerwelle (alle 5 min) und Wetter/Nutzung (alle 10 min)
//
//  Füllgrad einer Station = Räder / (Räder + freie Plätze)
//  Radbewegungen = Summe aller Änderungen der Räderzahl (Ausleihen + Rückgaben)
// ============================================================
const cfg = global.get('cfg');
const P = cfg.prefix, S = cfg.stats;
let st = context.get('st');
if (!st || st.prefix !== P) {
    st = { prefix: P, stations: {}, bikes: {}, moves: 0, weather: null, restored: false,
        hist: { wave: [], use: [] }, lastWave: 0, lastUse: Date.now(), lastSpatial: '' };
}
const t = msg.topic || '';
const p = msg.payload;
const empty = p === '' || p == null || (Buffer.isBuffer(p) && p.length === 0);
const out = [];

// Entfernung in km (Näherung, für Stadtentfernungen ausreichend)
const distKm = (a, b) => Math.hypot((a.lon - b.lon) * 111.32 * Math.cos(a.lat * Math.PI / 180), (a.lat - b.lat) * 110.54);

if (t.endsWith('/static/stations') && Array.isArray(p)) {
    st.stations = {};
    for (const s of p) {
        const d = distKm(s, S.center);
        st.stations[s.id] = { distKm: Math.round(d * 100) / 100, zone: d <= S.centerRadiusKm ? 'Zentrum' : 'Stadtrand' };
    }
} else if (t.indexOf('/live/bicimad/') >= 0) {
    if (empty || typeof p !== 'object') return null;
    const id = t.split('/').pop();
    const prev = st.bikes[id];
    // retain=true = vom Broker nachgeliefert (Startzustand), keine echte Bewegung
    if (prev && !msg.retain) st.moves += Math.abs((p.bikes || 0) - prev.bikes);
    st.bikes[id] = { bikes: p.bikes || 0, docks: p.docks || 0, ts: p.ts || Date.now() };
} else if (t.endsWith('/live/weather')) {
    if (empty || typeof p !== 'object') return null;
    st.weather = { temp: p.temp, precip: p.precip, wind: p.wind, ts: p.ts };
} else if (t.endsWith('/stats/history')) {
    // Nur einmal nach dem Start: gespeicherten Verlauf übernehmen (danach sind es unsere eigenen Nachrichten)
    if (!st.restored && !empty && typeof p === 'object') {
        st.hist = { wave: Array.isArray(p.wave) ? p.wave : [], use: Array.isArray(p.use) ? p.use : [] };
        const lw = st.hist.wave[st.hist.wave.length - 1];
        if (lw) st.lastWave = lw.t;
        node.warn('Verlauf übernommen: ' + st.hist.wave.length + ' Punkte Pendlerwelle, ' + st.hist.use.length + ' Punkte Wetter/Nutzung');
    }
    st.restored = true;
    context.set('st', st);
    return null;
}

// ---------- Auswertung nur im Takt (jede Minute) ----------
if (t !== 'tick') { context.set('st', st); return null; }
st.restored = true;                        // spätestens jetzt: kein späteres Überschreiben mehr
const now = Date.now();

// aktuelle Lage: nur Stationen mit frischen Daten
const fresh = Object.keys(st.bikes).filter(id => st.stations[id] && now - st.bikes[id].ts < S.freshMin * 60000);
const zone = { Zentrum: { b: 0, slots: 0 }, Stadtrand: { b: 0, slots: 0 } };
let total = 0, emptySt = 0, fullSt = 0;
const points = [];
for (const id of fresh) {
    const b = st.bikes[id], s = st.stations[id];
    const slots = b.bikes + b.docks;
    total += b.bikes;
    if (b.bikes === 0) emptySt++;
    if (b.docks === 0) fullSt++;
    if (slots > 0) {
        zone[s.zone].b += b.bikes; zone[s.zone].slots += slots;
        points.push([s.distKm, Math.round(b.bikes / slots * 100)]);
    }
}
const pct = z => z.slots ? Math.round(z.b / z.slots * 1000) / 10 : null;
if (!fresh.length) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'keine frischen BiciMAD-Daten (läuft collector.py?)' });
    context.set('st', st);
    return null;
}

// Zentrum gegen Stadtrand (Momentaufnahme, nur senden wenn sich etwas geändert hat)
const sig = JSON.stringify(points);
if (sig !== st.lastSpatial) {
    st.lastSpatial = sig;
    out.push({ topic: P + '/stats/spatial', qos: 0, retain: true,
        payload: { points: points, centerRadiusKm: S.centerRadiusKm, ts: now } });
}

let histChanged = false;
// Pendlerwelle: alle S.waveEveryMin Minuten ein Punkt
if (now - st.lastWave >= S.waveEveryMin * 60000 - 5000) {
    st.lastWave = now;
    st.hist.wave.push({ t: now, center: pct(zone.Zentrum), edge: pct(zone.Stadtrand), total: total });
    st.hist.wave = st.hist.wave.filter(w => now - w.t <= S.waveKeepH * 3600000);
    histChanged = true;
}
// Wetter und Radnutzung: alle S.useEveryMin Minuten ein Punkt (Bewegungen im Intervall + Wetter)
const movesNow = st.moves;
if (now - st.lastUse >= S.useEveryMin * 60000 - 5000) {
    const w = st.weather && now - st.weather.ts < 30 * 60000 ? st.weather : null;
    if (w) st.hist.use.push({ t: now, moves: st.moves, temp: w.temp, precip: w.precip, wind: w.wind });
    st.hist.use = st.hist.use.filter(u => now - u.t <= S.useKeepD * 86400000);
    st.moves = 0;
    st.lastUse = now;
    histChanged = true;
}
if (histChanged) out.push({ topic: P + '/stats/history', qos: 1, retain: true, payload: st.hist });

out.push({ topic: P + '/stats/now', qos: 0, retain: true, payload: {
    stations: fresh.length, bikes: total, empty: emptySt, full: fullSt,
    center: pct(zone.Zentrum), edge: pct(zone.Stadtrand),
    movesSoFar: movesNow, movesWindowMin: S.useEveryMin, ts: now } });

context.set('st', st);
node.status({ fill: 'green', shape: 'dot', text: fresh.length + ' Stationen, ' + total + ' Räder, Zentrum ' +
    pct(zone.Zentrum) + ' %, Rand ' + pct(zone.Stadtrand) + ' %' });
return [out];

// Kennzahlen "Madrid jetzt" (Seite "Statistik", oben)
//   .../stats/now   Räder, leere/volle Stationen, Füllgrad Zentrum/Stadtrand
//   .../live/weather  aktuelles Wetter + Regen in der nächsten Stunde
//   .../system/+    Status der Datenquellen (Birth / Close / Last Will)
//   .../stats/history  letzter Wert "Radbewegungen pro 10 min"
const cfg = global.get('cfg');
let k = context.get('k');
if (!k || k.prefix !== cfg.prefix) k = { prefix: cfg.prefix, now: null, weather: null, system: {}, moves: null };
const t = msg.topic || '', p = msg.payload;
const empty = p === '' || p == null || (Buffer.isBuffer(p) && p.length === 0);
if (t.endsWith('/stats/now') && !empty) k.now = p;
else if (t.endsWith('/live/weather') && !empty) k.weather = p;
else if (t.indexOf('/system/') >= 0) k.system[t.split('/').pop()] = empty ? null : String(p);
else if (t.endsWith('/stats/history') && !empty) {
    const u = (p.use || []).slice(-1)[0];
    k.moves = u ? { moves: u.moves, t: u.t } : null;
}
context.set('k', k);

const hm = ms => new Date(ms).toLocaleTimeString('de-DE', { timeZone: 'Europe/Madrid', hour: '2-digit', minute: '2-digit' });
const num = x => x == null ? '–' : String(Math.round(x * 10) / 10).replace('.', ',');
const fmt = n => n == null ? '–' : String(n).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
let weather = null;
if (k.weather) {
    const w = k.weather;
    const next = (w.forecast || []).filter(f => f.t + 15 * 60000 > Date.now() && f.t <= Date.now() + 3600000);
    const maxP = next.length ? Math.max(...next.map(f => f.precip || 0)) : null;
    const rainAt = next.find(f => (f.precip || 0) >= 0.1);
    weather = { temp: num(w.temp), wind: Math.round(w.wind), precipNow: num(w.precip),
        now: (w.precip || 0) >= 0.1 ? 'Regen' : 'trocken',
        nextHour: maxP == null ? 'keine Vorhersage' : rainAt ? 'Regen ab ' + hm(rainAt.t) + ' (bis ' + num(maxP) + ' mm)' : 'nächste Stunde trocken',
        at: hm(w.ts) };
}
const names = { bicimad: 'BiciMAD', weather: 'Wetter', fahrplan: 'Fahrplan', emt: 'EMT-Bus' };
const sources = ['bicimad', 'weather', 'fahrplan', 'emt'].map(n => {
    const s = k.system[n];
    return { name: names[n], state: !s ? 'aus' : s.indexOf('online') === 0 ? 'ok' : 'fehlt', text: s || (n === 'emt' ? 'nicht eingerichtet' : 'noch nie gemeldet') };
});
const n = k.now;
return { payload: {
    weather: weather,
    bikes: n ? { total: fmt(n.bikes), stations: n.stations, empty: n.empty, full: n.full,
        center: num(n.center), edge: num(n.edge), at: hm(n.ts) } : null,
    moves: k.moves ? { value: fmt(k.moves.moves), at: hm(k.moves.t) } : null,
    sources: sources,
    collectorDown: sources[0].state !== 'ok'
} };

// Statistik -> Diagramme (die Diagramme werden jedes Mal komplett ersetzt: action "replace")
//   .../stats/history -> 1: Pendlerwelle  3: Radbewegungen je 10 min  4: Temperatur
//   .../stats/spatial -> 2: Zentrum gegen Stadtrand
// Die Reihen stehen als Eigenschaften im Punkt ({x, Zentrum, Stadtrand}); im Diagramm-Knoten
// ist "Series" eine feste JSON-Liste -> Farben und Reihenfolge der Legende bleiben stabil.
const t = msg.topic || '', p = msg.payload;
if (p == null || typeof p !== 'object') return null;
const r1 = x => x == null ? null : Math.round(x * 10) / 10;
if (t.endsWith('/stats/history')) {
    // erst ab 2 Punkten zeichnen (ein einzelner Punkt verzerrt die Zeitachse)
    const wave = (p.wave || []).length < 2 ? [] : p.wave.map(w => ({ x: w.t, Zentrum: w.center, Stadtrand: w.edge }));
    const use = p.use || [];
    const moves = use.map(u => (u.precip || 0) >= 0.1 ? { x: u.t, trocken: null, Regen: u.moves } : { x: u.t, trocken: u.moves, Regen: null });
    const temp = use.map(u => ({ x: u.t, 'Temperatur (°C)': r1(u.temp), 'Wind (km/h)': r1(u.wind) }));
    const m = (arr) => ({ payload: arr.length ? arr : [], action: 'replace' });
    return [m(wave), null, m(moves), m(temp)];
}
if (t.endsWith('/stats/spatial')) {
    const pts = (p.points || []).map(a => a[0] <= p.centerRadiusKm ? { x: a[0], Zentrum: a[1] } : { x: a[0], Stadtrand: a[1] });
    return [null, { payload: pts.length ? pts : [], action: 'replace' }, null, null];
}
return null;
